  16: package com.cockpitbench.foundation.core;
  17: 
  18: import java.util.ArrayList;
  19: import java.util.Collection;
  20: import java.util.Collections;
  21: import java.util.Comparator;
  22: import java.util.EnumMap;
  23: import java.util.List;
  24: import java.util.Map;
  25: import java.util.Objects;
  26: 
  27: /** Produces deterministic retention actions for identity audit partitions. */
  28: public final class AuditRetentionPlanner {
  29:     public enum Category {
  30:         AUTHENTICATION,
  31:         ACCOUNT_CHANGE,
  32:         CONSENT_CHANGE,
  33:         ROLE_CHANGE,
  34:         DEVICE_BINDING,
  35:         SECURITY_ALERT,
  36:         PROVIDER_HEALTH,
  37:         PRIVACY_EXPORT
  38:     }
  39: 
  40:     public enum ActionKind {
  41:         KEEP,
  42:         COMPACT,
  43:         ARCHIVE,
  44:         DELETE,
  45:         HOLD
  46:     }
  47: 
  48:     public static final class Rule {
  49:         public final Category category;
  50:         public final long hotRetentionMillis;
  51:         public final long archiveRetentionMillis;
  52:         public final int compactionFactor;
  53:         public final boolean securityHoldEligible;
  54: 
  55:         public Rule(
  56:                 Category category,
  57:                 long hotRetentionMillis,
  58:                 long archiveRetentionMillis,
  59:                 int compactionFactor,
  60:                 boolean securityHoldEligible) {
  61:             this.category = Objects.requireNonNull(category, "category");
  62:             this.hotRetentionMillis = hotRetentionMillis;
  63:             this.archiveRetentionMillis = archiveRetentionMillis;
  64:             this.compactionFactor = compactionFactor;
  65:             this.securityHoldEligible = securityHoldEligible;
  66:             if (hotRetentionMillis <= 0 || archiveRetentionMillis < hotRetentionMillis) {
  67:                 throw new IllegalArgumentException("invalid retention interval");
  68:             }
  69:             if (compactionFactor <= 0) {
  70:                 throw new IllegalArgumentException("compaction factor must be positive");
  71:             }
  72:         }
  73:     }
  74: 
  75:     public static final class Partition {
  76:         public final String id;
  77:         public final Category category;
  78:         public final long firstEventAt;
  79:         public final long lastEventAt;
  80:         public final long eventCount;
  81:         public final long bytes;
  82:         public final boolean archived;
  83:         public final boolean legalHold;
  84: 
  85:         public Partition(
  86:                 String id,
  87:                 Category category,
  88:                 long firstEventAt,
  89:                 long lastEventAt,
  90:                 long eventCount,
  91:                 long bytes,
  92:                 boolean archived,
  93:                 boolean legalHold) {
  94:             this.id = require(id, "id");
  95:             this.category = Objects.requireNonNull(category, "category");
  96:             this.firstEventAt = firstEventAt;
  97:             this.lastEventAt = lastEventAt;
  98:             this.eventCount = eventCount;
  99:             this.bytes = bytes;
 100:             this.archived = archived;
 101:             this.legalHold = legalHold;
 102:             if (firstEventAt < 0
 103:                     || lastEventAt < firstEventAt
 104:                     || eventCount < 0
 105:                     || bytes < 0) {
 106:                 throw new IllegalArgumentException("invalid partition metrics");
 107:             }
 108:         }
 109:     }
 110: 
 111:     public static final class Action {
 112:         public final String partitionId;
 113:         public final ActionKind kind;
 114:         public final String reason;
 115:         public final long estimatedBytesAfter;
 116:         public final long eventsAfter;
 117: 
 118:         Action(
 119:                 String partitionId,
 120:                 ActionKind kind,
 121:                 String reason,
 122:                 long estimatedBytesAfter,
 123:                 long eventsAfter) {
 124:             this.partitionId = partitionId;
 125:             this.kind = kind;
 126:             this.reason = reason;
 127:             this.estimatedBytesAfter = estimatedBytesAfter;
 128:             this.eventsAfter = eventsAfter;
 129:         }
 130:     }
 131: 
 132:     public static final class Plan {
 133:         public final List<Action> actions;
 134:         public final long bytesBefore;
 135:         public final long bytesAfter;
 136:         public final long eventsBefore;
 137:         public final long eventsAfter;
 138: 
 139:         Plan(
 140:                 List<Action> actions,
 141:                 long bytesBefore,
 142:                 long bytesAfter,
 143:                 long eventsBefore,
 144:                 long eventsAfter) {
 145:             this.actions = Collections.unmodifiableList(new ArrayList<>(actions));
 146:             this.bytesBefore = bytesBefore;
 147:             this.bytesAfter = bytesAfter;
 148:             this.eventsBefore = eventsBefore;
 149:             this.eventsAfter = eventsAfter;
 150:         }
 151:     }
 152: 
 153:     private final Map<Category, Rule> rules;
 154: 
 155:     public AuditRetentionPlanner(Collection<Rule> rules) {
 156:         Map<Category, Rule> indexed = new EnumMap<>(Category.class);
 157:         for (Rule rule : Objects.requireNonNull(rules, "rules")) {
 158:             if (indexed.put(rule.category, rule) != null) {
 159:                 throw new IllegalArgumentException("duplicate retention rule: " + rule.category);
 160:             }
 161:         }
 162:         this.rules = Collections.unmodifiableMap(indexed);
 163:     }
 164: 
 165:     public Plan plan(Collection<Partition> partitions, long now, long byteBudget) {
 166:         if (now < 0 || byteBudget < 0) {
 167:             throw new IllegalArgumentException("plan values must not be negative");
 168:         }
 169:         List<Partition> ordered = new ArrayList<>(
 170:                 Objects.requireNonNull(partitions, "partitions"));
 171:         ordered.sort(Comparator.comparing((Partition value) -> value.category.name())
 172:                 .thenComparingLong(value -> value.lastEventAt)
 173:                 .thenComparing(value -> value.id));
 174:         List<Action> actions = new ArrayList<>();
 175:         long bytesBefore = 0;
 176:         long bytesAfter = 0;
 177:         long eventsBefore = 0;
 178:         long eventsAfter = 0;
 179:         for (Partition partition : ordered) {
 180:             bytesBefore += partition.bytes;
 181:             eventsBefore += partition.eventCount;
 182:             Rule rule = rules.get(partition.category);
 183:             Action action = decide(rule, partition, now, byteBudget, bytesAfter);
 184:             actions.add(action);
 185:             bytesAfter += action.estimatedBytesAfter;
 186:             eventsAfter += action.eventsAfter;
 187:         }
 188:         return new Plan(
 189:                 actions,
 190:                 bytesBefore,
 191:                 bytesAfter,
 192:                 eventsBefore,
 193:                 eventsAfter);
 194:     }
 195: 
 196:     private static Action decide(
 197:             Rule rule,
 198:             Partition partition,
 199:             long now,
 200:             long byteBudget,
 201:             long bytesAlreadyKept) {
 202:         if (rule == null) {
 203:             return new Action(
 204:                     partition.id,
 205:                     ActionKind.HOLD,
 206:                     "no retention rule",
 207:                     partition.bytes,
 208:                     partition.eventCount);
 209:         }
 210:         if (partition.legalHold) {
 211:             return new Action(
 212:                     partition.id,
 213:                     ActionKind.HOLD,
 214:                     "legal hold",
 215:                     partition.bytes,
 216:                     partition.eventCount);
 217:         }
 218:         long age = Math.max(0, now - partition.lastEventAt);
 219:         if (age >= rule.archiveRetentionMillis) {
 220:             return new Action(partition.id, ActionKind.DELETE, "retention elapsed", 0, 0);
 221:         }
 222:         if (partition.archived) {
 223:             return new Action(
 224:                     partition.id,
 225:                     ActionKind.KEEP,
 226:                     "within archive retention",
 227:                     partition.bytes,
 228:                     partition.eventCount);
 229:         }
 230:         if (age >= rule.hotRetentionMillis) {
 231:             return new Action(
 232:                     partition.id,
 233:                     ActionKind.ARCHIVE,
 234:                     "hot retention elapsed",
 235:                     Math.max(1, partition.bytes / 2),
 236:                     partition.eventCount);
 237:         }
 238:         if (bytesAlreadyKept + partition.bytes > byteBudget) {
 239:             long compactedEvents = Math.max(1, partition.eventCount / rule.compactionFactor);
 240:             long compactedBytes = Math.max(1, partition.bytes / rule.compactionFactor);
 241:             return new Action(
 242:                     partition.id,
 243:                     ActionKind.COMPACT,
 244:                     "byte budget pressure",
 245:                     compactedBytes,
 246:                     compactedEvents);
 247:         }
 248:         return new Action(
 249:                 partition.id,
 250:                 ActionKind.KEEP,
 251:                 "within hot retention",
 252:                 partition.bytes,
 253:                 partition.eventCount);
 254:     }
 255: 
 256:     private static String require(String value, String name) {
 257:         Objects.requireNonNull(value, name);
 258:         if (value.trim().isEmpty()) {
 259:             throw new IllegalArgumentException(name + " must not be empty");
 260:         }
 261:         return value;
 262:     }
 263: }
