  16: package com.cockpitbench.foundation.core; import java.util.*; public final class BackoffPolicy { private final Map<String,Integer> attempts=new HashMap<>(); public synchronized long failure(String key,Throwable error){if(error instanceof SecurityException)return -1;int count=attempts.getOrDefault(key,0)+1;attempts.put(key,count);return count>5?-1:Math.min(30000,500L<<(count-1));} public synchronized void success(String key){attempts.remove(key);} }
