  16: package com.cockpitbench.foundation.core;
  17: 
  18: import java.util.ArrayList;
  19: import java.util.Collection;
  20: import java.util.Collections;
  21: import java.util.LinkedHashMap;
  22: import java.util.LinkedHashSet;
  23: import java.util.List;
  24: import java.util.Map;
  25: import java.util.Objects;
  26: import java.util.Set;
  27: 
  28: /** Centralizes cross-user and occupant-zone access before Binder work is dispatched. */
  29: public final class CrossUserAccessBoundary {
  30:     public enum Scope {
  31:         SELF,
  32:         CURRENT_OCCUPANT,
  33:         SAME_ZONE,
  34:         ANY_OCCUPANT,
  35:         SYSTEM
  36:     }
  37: 
  38:     public enum Outcome {
  39:         ALLOW,
  40:         DENY,
  41:         REQUIRE_USER_CONFIRMATION,
  42:         REQUIRE_SYSTEM_DELEGATION
  43:     }
  44: 
  45:     public static final class Caller {
  46:         public final int uid;
  47:         public final int userId;
  48:         public final String packageName;
  49:         public final String zone;
  50:         public final Set<String> permissions;
  51:         public final boolean systemUid;
  52: 
  53:         public Caller(
  54:                 int uid,
  55:                 int userId,
  56:                 String packageName,
  57:                 String zone,
  58:                 Collection<String> permissions,
  59:                 boolean systemUid) {
  60:             this.uid = uid;
  61:             this.userId = userId;
  62:             this.packageName = require(packageName, "packageName");
  63:             this.zone = require(zone, "zone");
  64:             this.permissions = immutableSet(permissions);
  65:             this.systemUid = systemUid;
  66:             if (uid < 0 || userId < 0) {
  67:                 throw new IllegalArgumentException("caller identifiers must not be negative");
  68:             }
  69:         }
  70:     }
  71: 
  72:     public static final class Target {
  73:         public final int userId;
  74:         public final String accountId;
  75:         public final String zone;
  76:         public final boolean activeOccupant;
  77: 
  78:         public Target(int userId, String accountId, String zone, boolean activeOccupant) {
  79:             this.userId = userId;
  80:             this.accountId = require(accountId, "accountId");
  81:             this.zone = require(zone, "zone");
  82:             this.activeOccupant = activeOccupant;
  83:             if (userId < 0) {
  84:                 throw new IllegalArgumentException("target user must not be negative");
  85:             }
  86:         }
  87:     }
  88: 
  89:     public static final class Rule {
  90:         public final String operation;
  91:         public final Scope scope;
  92:         public final Set<String> requiredPermissions;
  93:         public final boolean confirmationForInactiveOccupant;
  94:         public final boolean denyWhileDriving;
  95: 
  96:         public Rule(
  97:                 String operation,
  98:                 Scope scope,
  99:                 Collection<String> requiredPermissions,
 100:                 boolean confirmationForInactiveOccupant,
 101:                 boolean denyWhileDriving) {
 102:             this.operation = require(operation, "operation");
 103:             this.scope = Objects.requireNonNull(scope, "scope");
 104:             this.requiredPermissions = immutableSet(requiredPermissions);
 105:             this.confirmationForInactiveOccupant = confirmationForInactiveOccupant;
 106:             this.denyWhileDriving = denyWhileDriving;
 107:         }
 108:     }
 109: 
 110:     public static final class Request {
 111:         public final Caller caller;
 112:         public final Target target;
 113:         public final String operation;
 114:         public final boolean vehicleMoving;
 115:         public final boolean userConfirmed;
 116:         public final String delegationToken;
 117: 
 118:         public Request(
 119:                 Caller caller,
 120:                 Target target,
 121:                 String operation,
 122:                 boolean vehicleMoving,
 123:                 boolean userConfirmed,
 124:                 String delegationToken) {
 125:             this.caller = Objects.requireNonNull(caller, "caller");
 126:             this.target = Objects.requireNonNull(target, "target");
 127:             this.operation = require(operation, "operation");
 128:             this.vehicleMoving = vehicleMoving;
 129:             this.userConfirmed = userConfirmed;
 130:             this.delegationToken = delegationToken == null ? "" : delegationToken;
 131:         }
 132:     }
 133: 
 134:     public static final class Decision {
 135:         public final Outcome outcome;
 136:         public final String reason;
 137:         public final Rule rule;
 138:         public final List<String> missingPermissions;
 139:         public final boolean crossUser;
 140:         public final boolean crossZone;
 141: 
 142:         Decision(
 143:                 Outcome outcome,
 144:                 String reason,
 145:                 Rule rule,
 146:                 List<String> missingPermissions,
 147:                 boolean crossUser,
 148:                 boolean crossZone) {
 149:             this.outcome = outcome;
 150:             this.reason = reason;
 151:             this.rule = rule;
 152:             this.missingPermissions = Collections.unmodifiableList(
 153:                     new ArrayList<>(missingPermissions));
 154:             this.crossUser = crossUser;
 155:             this.crossZone = crossZone;
 156:         }
 157: 
 158:         public boolean allowed() {
 159:             return outcome == Outcome.ALLOW;
 160:         }
 161:     }
 162: 
 163:     private final Map<String, Rule> rules;
 164:     private final Set<String> validDelegations = new LinkedHashSet<>();
 165: 
 166:     public CrossUserAccessBoundary(Collection<Rule> rules) {
 167:         Map<String, Rule> indexed = new LinkedHashMap<>();
 168:         for (Rule rule : Objects.requireNonNull(rules, "rules")) {
 169:             if (indexed.put(rule.operation, rule) != null) {
 170:                 throw new IllegalArgumentException("duplicate operation rule: " + rule.operation);
 171:             }
 172:         }
 173:         this.rules = Collections.unmodifiableMap(indexed);
 174:     }
 175: 
 176:     public synchronized void registerDelegation(String token) {
 177:         validDelegations.add(require(token, "token"));
 178:     }
 179: 
 180:     public synchronized void revokeDelegation(String token) {
 181:         validDelegations.remove(token);
 182:     }
 183: 
 184:     public synchronized Decision evaluate(Request request) {
 185:         Rule rule = rules.get(request.operation);
 186:         boolean crossUser = request.caller.userId != request.target.userId;
 187:         boolean crossZone = !request.caller.zone.equals(request.target.zone);
 188:         if (rule == null) {
 189:             return decision(Outcome.DENY, "operation has no policy", null, crossUser, crossZone);
 190:         }
 191:         if (rule.denyWhileDriving && request.vehicleMoving) {
 192:             return decision(Outcome.DENY, "operation blocked while driving", rule, crossUser, crossZone);
 193:         }
 194:         List<String> missing = new ArrayList<>();
 195:         for (String permission : rule.requiredPermissions) {
 196:             if (!request.caller.permissions.contains(permission)) {
 197:                 missing.add(permission);
 198:             }
 199:         }
 200:         Collections.sort(missing);
 201:         if (!missing.isEmpty() && !request.caller.systemUid) {
 202:             return new Decision(
 203:                     Outcome.DENY,
 204:                     "required permission missing",
 205:                     rule,
 206:                     missing,
 207:                     crossUser,
 208:                     crossZone);
 209:         }
 210:         Outcome scopeOutcome = checkScope(rule.scope, request, crossUser, crossZone);
 211:         if (scopeOutcome != Outcome.ALLOW) {
 212:             return decision(scopeOutcome, "requested scope exceeded", rule, crossUser, crossZone);
 213:         }
 214:         if (rule.confirmationForInactiveOccupant
 215:                 && !request.target.activeOccupant
 216:                 && !request.userConfirmed) {
 217:             return decision(
 218:                     Outcome.REQUIRE_USER_CONFIRMATION,
 219:                     "inactive occupant confirmation required",
 220:                     rule,
 221:                     crossUser,
 222:                     crossZone);
 223:         }
 224:         return decision(Outcome.ALLOW, "policy satisfied", rule, crossUser, crossZone);
 225:     }
 226: 
 227:     private Outcome checkScope(
 228:             Scope scope,
 229:             Request request,
 230:             boolean crossUser,
 231:             boolean crossZone) {
 232:         switch (scope) {
 233:             case SELF:
 234:                 return crossUser ? Outcome.DENY : Outcome.ALLOW;
 235:             case CURRENT_OCCUPANT:
 236:                 return request.target.activeOccupant ? Outcome.ALLOW : Outcome.DENY;
 237:             case SAME_ZONE:
 238:                 return crossZone ? Outcome.DENY : Outcome.ALLOW;
 239:             case ANY_OCCUPANT:
 240:                 if (!crossUser) {
 241:                     return Outcome.ALLOW;
 242:                 }
 243:                 return validDelegations.contains(request.delegationToken)
 244:                         ? Outcome.ALLOW
 245:                         : Outcome.REQUIRE_SYSTEM_DELEGATION;
 246:             case SYSTEM:
 247:                 return request.caller.systemUid ? Outcome.ALLOW : Outcome.DENY;
 248:             default:
 249:                 throw new IllegalStateException("unsupported scope: " + scope);
 250:         }
 251:     }
 252: 
 253:     private static Decision decision(
 254:             Outcome outcome,
 255:             String reason,
 256:             Rule rule,
 257:             boolean crossUser,
 258:             boolean crossZone) {
 259:         return new Decision(
 260:                 outcome,
 261:                 reason,
 262:                 rule,
 263:                 Collections.emptyList(),
 264:                 crossUser,
 265:                 crossZone);
 266:     }
 267: 
 268:     private static Set<String> immutableSet(Collection<String> values) {
 269:         return Collections.unmodifiableSet(
 270:                 new LinkedHashSet<>(Objects.requireNonNull(values, "values")));
 271:     }
 272: 
