  30: /** Evaluates bound-device evidence without leaking provider-specific details into sessions. */
  31: public final class DeviceTrustEngine {
  32:     public enum SignalKind {
  33:         HARDWARE_ATTESTATION,
  34:         SECURE_CHANNEL,
  35:         RECENT_OWNER_APPROVAL,
  36:         PROXIMITY,
  37:         BIOMETRIC,
  38:         COMPANION_APP,
  39:         VEHICLE_KEY,
  40:         NETWORK_REPUTATION,
  41:         CLOCK_INTEGRITY,
  42:         TAMPER_DETECTION
  43:     }
  44: 
  45:     public enum Verdict {
  46:         TRUSTED,
  47:         LIMITED,
  48:         CHALLENGE_REQUIRED,
  49:         REJECTED
  50:     }
  51: 
  52:     public static final class Signal {
  53:         public final SignalKind kind;
  54:         public final boolean passed;
  55:         public final int confidence;
  56:         public final long observedAt;
  57:         public final String source;
  58: 
  59:         public Signal(
  60:                 SignalKind kind,
  61:                 boolean passed,
  62:                 int confidence,
  63:                 long observedAt,
  64:                 String source) {
  65:             this.kind = Objects.requireNonNull(kind, "kind");
  66:             this.passed = passed;
  67:             this.confidence = confidence;
  68:             this.observedAt = observedAt;
  69:             this.source = require(source, "source");
  70:             if (confidence < 0 || confidence > 100) {
  71:                 throw new IllegalArgumentException("confidence out of range");
  72:             }
  73:             if (observedAt < 0) {
  74:                 throw new IllegalArgumentException("observedAt must not be negative");
  75:             }
  76:         }
  77:     }
  78: 
  79:     public static final class Policy {
  80:         public final String id;
  81:         public final long maximumAgeMillis;
  82:         public final int trustedThreshold;
  83:         public final int limitedThreshold;
  84:         public final Set<SignalKind> required;
  85:         public final Map<SignalKind, Integer> weights;
  86:         public final boolean rejectTamper;
  87: 
  88:         public Policy(
  89:                 String id,
  90:                 long maximumAgeMillis,
  91:                 int trustedThreshold,
  92:                 int limitedThreshold,
  93:                 Collection<SignalKind> required,
  94:                 Map<SignalKind, Integer> weights,
  95:                 boolean rejectTamper) {
  96:             this.id = require(id, "id");
  97:             this.maximumAgeMillis = maximumAgeMillis;
  98:             this.trustedThreshold = trustedThreshold;
  99:             this.limitedThreshold = limitedThreshold;
 100:             this.required = Collections.unmodifiableSet(
 101:                     EnumSet.copyOf(Objects.requireNonNull(required, "required")));
 102:             this.weights = Collections.unmodifiableMap(
 103:                     new EnumMap<>(Objects.requireNonNull(weights, "weights")));
 104:             this.rejectTamper = rejectTamper;
 105:             if (maximumAgeMillis <= 0) {
 106:                 throw new IllegalArgumentException("maximumAgeMillis must be positive");
 107:             }
 108:             if (trustedThreshold <= limitedThreshold) {
 109:                 throw new IllegalArgumentException("trusted threshold must exceed limited threshold");
 110:             }
 111:             for (Integer weight : this.weights.values()) {
 112:                 if (weight == null || weight < -100 || weight > 100) {
 113:                     throw new IllegalArgumentException("signal weight out of range");
 114:                 }
 115:             }
 116:         }
 117:     }
 118: 
 119:     public static final class EvidenceResult {
 120:         public final Signal signal;
 121:         public final boolean fresh;
 122:         public final int contribution;
 123:         public final String detail;
 124: 
 125:         EvidenceResult(Signal signal, boolean fresh, int contribution, String detail) {
 126:             this.signal = signal;
 127:             this.fresh = fresh;
 128:             this.contribution = contribution;
 129:             this.detail = detail;
 130:         }
 131:     }
 132: 
 133:     public static final class Assessment {
 134:         public final String policyId;
 135:         public final Verdict verdict;
 136:         public final int score;
 137:         public final List<SignalKind> missingRequired;
 138:         public final List<EvidenceResult> evidence;
 139:         public final long evaluatedAt;
 140: 
 141:         Assessment(
 142:                 String policyId,
 143:                 Verdict verdict,
 144:                 int score,
 145:                 List<SignalKind> missingRequired,
 146:                 List<EvidenceResult> evidence,
 147:                 long evaluatedAt) {
 148:             this.policyId = policyId;
 149:             this.verdict = verdict;
 150:             this.score = score;
 151:             this.missingRequired = Collections.unmodifiableList(
 152:                     new ArrayList<>(missingRequired));
 153:             this.evidence = Collections.unmodifiableList(new ArrayList<>(evidence));
 154:             this.evaluatedAt = evaluatedAt;
 155:         }
 156: 
 157:         public boolean permitsCredentialRelease() {
 158:             return verdict == Verdict.TRUSTED;
 159:         }
 160: 
 161:         public boolean permitsLimitedSession() {
 162:             return verdict == Verdict.TRUSTED || verdict == Verdict.LIMITED;
 163:         }
 164:     }
 165: 
 166:     public Assessment assess(Policy policy, Collection<Signal> signals, long now) {
 167:         Objects.requireNonNull(policy, "policy");
 168:         if (now < 0) {
 169:             throw new IllegalArgumentException("now must not be negative");
 170:         }
 171:         Map<SignalKind, Signal> newest = newestSignals(signals);
 172:         List<EvidenceResult> evidence = new ArrayList<>();
 173:         List<SignalKind> missing = new ArrayList<>();
 174:         int score = 0;
 175:         boolean tamperDetected = false;
 176: 
 177:         for (SignalKind kind : SignalKind.values()) {
 178:             Signal signal = newest.get(kind);
 179:             if (signal == null) {
 180:                 if (policy.required.contains(kind)) {
 181:                     missing.add(kind);
 182:                 }
 183:                 continue;
 184:             }
 185:             long age = Math.max(0, now - signal.observedAt);
 186:             boolean fresh = age <= policy.maximumAgeMillis;
 187:             int configuredWeight = policy.weights.getOrDefault(kind, 0);
 188:             int confidenceAdjusted = configuredWeight * signal.confidence / 100;
 189:             int contribution = signal.passed && fresh
 190:                     ? confidenceAdjusted
 191:                     : -Math.abs(confidenceAdjusted);
 192:             score += contribution;
 193:             if (kind == SignalKind.TAMPER_DETECTION && !signal.passed && fresh) {
 194:                 tamperDetected = true;
 195:             }
 196:             if (policy.required.contains(kind) && (!signal.passed || !fresh)) {
 197:                 missing.add(kind);
 198:             }
 199:             evidence.add(new EvidenceResult(
 200:                     signal,
 201:                     fresh,
 202:                     contribution,
 203:                     detail(signal, fresh, age)));
 204:         }
 205: 
 206:         score = Math.max(-100, Math.min(100, score));
 207:         missing.sort(Comparator.comparing(Enum::name));
 208:         evidence.sort(Comparator.comparing(value -> value.signal.kind.name()));
 209:         Verdict verdict = verdict(policy, score, missing, tamperDetected);
 210:         return new Assessment(policy.id, verdict, score, missing, evidence, now);
 211:     }
 212: 
 213:     public Map<String, Assessment> assessFleet(
 214:             Policy policy,
 215:             Map<String, ? extends Collection<Signal>> fleetEvidence,
 216:             long now) {
 217:         Map<String, Assessment> results = new LinkedHashMap<>();
 218:         List<String> ids = new ArrayList<>(fleetEvidence.keySet());
 219:         Collections.sort(ids);
 220:         for (String deviceId : ids) {
 221:             results.put(deviceId, assess(policy, fleetEvidence.get(deviceId), now));
 222:         }
 223:         return Collections.unmodifiableMap(results);
 224:     }
 225: 
 226:     private static Map<SignalKind, Signal> newestSignals(Collection<Signal> signals) {
 227:         Map<SignalKind, Signal> newest = new EnumMap<>(SignalKind.class);
 228:         for (Signal signal : Objects.requireNonNull(signals, "signals")) {
 229:             Signal current = newest.get(signal.kind);
 230:             if (current == null || signal.observedAt > current.observedAt) {
 231:                 newest.put(signal.kind, signal);
 232:             }
 233:         }
 234:         return newest;
 235:     }
 236: 
 237:     private static Verdict verdict(
 238:             Policy policy,
 239:             int score,
 240:             List<SignalKind> missing,
 241:             boolean tamperDetected) {
 242:         if (policy.rejectTamper && tamperDetected) {
 243:             return Verdict.REJECTED;
 244:         }
 245:         if (!missing.isEmpty()) {
 246:             return score >= policy.limitedThreshold
 247:                     ? Verdict.CHALLENGE_REQUIRED
 248:                     : Verdict.REJECTED;
 249:         }
 250:         if (score >= policy.trustedThreshold) {
 251:             return Verdict.TRUSTED;
 252:         }
 253:         if (score >= policy.limitedThreshold) {
 254:             return Verdict.LIMITED;
 255:         }
 256:         return Verdict.CHALLENGE_REQUIRED;
 257:     }
 258: 
 259:     private static String detail(Signal signal, boolean fresh, long age) {
 260:         if (!fresh) {
 261:             return "stale:" + age;
 262:         }
 263:         if (!signal.passed) {
 264:             return "failed:" + signal.source;
 265:         }
 266:         return "accepted:" + signal.source;
 267:     }
 268: 
 269:     private static String require(String value, String name) {
 270:         Objects.requireNonNull(value, name);
 271:         if (value.trim().isEmpty()) {
 272:             throw new IllegalArgumentException(name + " must not be empty");
 273:         }
 274:         return value;
 275:     }
 276: }
