  31: /** Deterministic policy evaluator for identity operations across occupants and zones. */
  32: public final class PolicyRuntime {
  33:     public enum Effect {
  34:         ALLOW,
  35:         DENY,
  36:         REQUIRE_CONSENT,
  37:         REQUIRE_REAUTHENTICATION
  38:     }
  39: 
  40:     public enum Operator {
  41:         EQUALS,
  42:         NOT_EQUALS,
  43:         CONTAINS,
  44:         IN,
  45:         GREATER_THAN,
  46:         LESS_THAN,
  47:         PRESENT
  48:     }
  49: 
  50:     public static final class Condition {
  51:         public final String attribute;
  52:         public final Operator operator;
  53:         public final String expected;
  54: 
  55:         public Condition(String attribute, Operator operator, String expected) {
  56:             this.attribute = requireToken(attribute, "attribute");
  57:             this.operator = Objects.requireNonNull(operator, "operator");
  58:             this.expected = expected == null ? "" : expected;
  59:         }
  60:     }
  61: 
  62:     public static final class Rule {
  63:         public final String id;
  64:         public final int priority;
  65:         public final String operation;
  66:         public final Effect effect;
  67:         public final List<Condition> conditions;
  68:         public final String reason;
  69: 
  70:         public Rule(
  71:                 String id,
  72:                 int priority,
  73:                 String operation,
  74:                 Effect effect,
  75:                 Collection<Condition> conditions,
  76:                 String reason) {
  77:             this.id = requireToken(id, "id");
  78:             this.priority = priority;
  79:             this.operation = requireToken(operation, "operation");
  80:             this.effect = Objects.requireNonNull(effect, "effect");
  81:             this.conditions = immutableList(conditions);
  82:             this.reason = requireToken(reason, "reason");
  83:             if (priority < 0 || priority > 10_000) {
  84:                 throw new IllegalArgumentException("priority out of range");
  85:             }
  86:         }
  87:     }
  88: 
  89:     public static final class PolicySet {
  90:         public final String id;
  91:         public final int revision;
  92:         public final Effect defaultEffect;
  93:         public final List<Rule> rules;
  94: 
  95:         public PolicySet(String id, int revision, Effect defaultEffect, Collection<Rule> rules) {
  96:             this.id = requireToken(id, "id");
  97:             this.revision = revision;
  98:             this.defaultEffect = Objects.requireNonNull(defaultEffect, "defaultEffect");
  99:             List<Rule> ordered = new ArrayList<>(Objects.requireNonNull(rules, "rules"));
 100:             ordered.sort(Comparator.comparingInt((Rule value) -> value.priority).reversed()
 101:                     .thenComparing(value -> value.id));
 102:             validateRuleIds(ordered);
 103:             this.rules = Collections.unmodifiableList(ordered);
 104:             if (revision <= 0) {
 105:                 throw new IllegalArgumentException("revision must be positive");
 106:             }
 107:         }
 108:     }
 109: 
 110:     public static final class Request {
 111:         public final String operation;
 112:         public final String accountId;
 113:         public final int userId;
 114:         public final String zone;
 115:         public final Set<String> roles;
 116:         public final Map<String, String> attributes;
 117: 
 118:         public Request(
 119:                 String operation,
 120:                 String accountId,
 121:                 int userId,
 122:                 String zone,
 123:                 Collection<String> roles,
 124:                 Map<String, String> attributes) {
 125:             this.operation = requireToken(operation, "operation");
 126:             this.accountId = requireToken(accountId, "accountId");
 127:             this.userId = userId;
 128:             this.zone = requireToken(zone, "zone");
 129:             this.roles = immutableSet(roles);
 130:             this.attributes = Collections.unmodifiableMap(
 131:                     new LinkedHashMap<>(Objects.requireNonNull(attributes, "attributes")));
 132:         }
 133: 
 134:         public String attribute(String name) {
 135:             switch (name) {
 136:                 case "operation":
 137:                     return operation;
 138:                 case "accountId":
 139:                     return accountId;
 140:                 case "userId":
 141:                     return Integer.toString(userId);
 142:                 case "zone":
 143:                     return zone;
 144:                 case "roles":
 145:                     return String.join(",", roles);
 146:                 default:
 147:                     return attributes.get(name);
 148:             }
 149:         }
 150:     }
 151: 
 152:     public static final class TraceStep {
 153:         public final String ruleId;
 154:         public final boolean operationMatched;
 155:         public final boolean conditionsMatched;
 156:         public final String detail;
 157: 
 158:         TraceStep(
 159:                 String ruleId,
 160:                 boolean operationMatched,
 161:                 boolean conditionsMatched,
 162:                 String detail) {
 163:             this.ruleId = ruleId;
 164:             this.operationMatched = operationMatched;
 165:             this.conditionsMatched = conditionsMatched;
 166:             this.detail = detail;
 167:         }
 168:     }
 169: 
 170:     public static final class Decision {
 171:         public final Effect effect;
 172:         public final String reason;
 173:         public final String ruleId;
 174:         public final int policyRevision;
 175:         public final List<TraceStep> trace;
 176: 
 177:         Decision(
 178:                 Effect effect,
 179:                 String reason,
 180:                 String ruleId,
 181:                 int policyRevision,
 182:                 List<TraceStep> trace) {
 183:             this.effect = effect;
 184:             this.reason = reason;
 185:             this.ruleId = ruleId;
 186:             this.policyRevision = policyRevision;
 187:             this.trace = Collections.unmodifiableList(new ArrayList<>(trace));
 188:         }
 189: 
 190:         public boolean permitsImmediateExecution() {
 191:             return effect == Effect.ALLOW;
 192:         }
 193: 
 194:         public boolean requiresUserInteraction() {
 195:             return effect == Effect.REQUIRE_CONSENT
 196:                     || effect == Effect.REQUIRE_REAUTHENTICATION;
 197:         }
 198:     }
 199: 
 200:     public Decision evaluate(PolicySet policy, Request request) {
 201:         Objects.requireNonNull(policy, "policy");
 202:         Objects.requireNonNull(request, "request");
 203:         List<TraceStep> trace = new ArrayList<>();
 204:         for (Rule rule : policy.rules) {
 205:             boolean operationMatched = matchesOperation(rule.operation, request.operation);
 206:             if (!operationMatched) {
 207:                 trace.add(new TraceStep(rule.id, false, false, "operation mismatch"));
 208:                 continue;
 209:             }
 210:             String mismatch = firstMismatch(rule.conditions, request);
 211:             boolean conditionsMatched = mismatch == null;
 212:             trace.add(new TraceStep(
 213:                     rule.id,
 214:                     true,
 215:                     conditionsMatched,
 216:                     conditionsMatched ? "matched" : mismatch));
 217:             if (conditionsMatched) {
 218:                 return new Decision(
 219:                         rule.effect,
 220:                         rule.reason,
 221:                         rule.id,
 222:                         policy.revision,
 223:                         trace);
 224:             }
 225:         }
 226:         return new Decision(
 227:                 policy.defaultEffect,
 228:                 "policy default",
 229:                 "",
 230:                 policy.revision,
 231:                 trace);
 232:     }
 233: 
 234:     public Map<String, Decision> evaluateBatch(
 235:             PolicySet policy,
 236:             Collection<Request> requests) {
 237:         Map<String, Decision> decisions = new LinkedHashMap<>();
 238:         for (Request request : Objects.requireNonNull(requests, "requests")) {
 239:             String key = request.accountId + ":" + request.operation + ":" + request.zone;
 240:             if (decisions.put(key, evaluate(policy, request)) != null) {
 241:                 throw new IllegalArgumentException("duplicate request key: " + key);
 242:             }
 243:         }
 244:         return Collections.unmodifiableMap(decisions);
 245:     }
 246: 
 247:     private static boolean matchesOperation(String ruleOperation, String requestedOperation) {
 248:         return ruleOperation.equals("*") || ruleOperation.equals(requestedOperation);
 249:     }
 250: 
 251:     private static String firstMismatch(List<Condition> conditions, Request request) {
 252:         for (Condition condition : conditions) {
 253:             String actual = request.attribute(condition.attribute);
 254:             if (!matches(condition, actual)) {
 255:                 return condition.attribute + " did not satisfy "
 256:                         + condition.operator.name().toLowerCase(Locale.ROOT);
 257:             }
 258:         }
 259:         return null;
 260:     }
 261: 
 262:     private static boolean matches(Condition condition, String actual) {
 263:         switch (condition.operator) {
 264:             case PRESENT:
 265:                 return actual != null && !actual.trim().isEmpty();
 266:             case EQUALS:
 267:                 return Objects.equals(actual, condition.expected);
 268:             case NOT_EQUALS:
 269:                 return !Objects.equals(actual, condition.expected);
 270:             case CONTAINS:
 271:                 return actual != null && containsToken(actual, condition.expected);
 272:             case IN:
 273:                 return actual != null && containsToken(condition.expected, actual);
 274:             case GREATER_THAN:
 275:                 return compareNumbers(actual, condition.expected) > 0;
 276:             case LESS_THAN:
 277:                 return compareNumbers(actual, condition.expected) < 0;
 278:             default:
 279:                 throw new IllegalStateException("unsupported operator: " + condition.operator);
 280:         }
 281:     }
 282: 
 283:     private static boolean containsToken(String values, String expected) {
 284:         for (String token : values.split(",")) {
 285:             if (token.trim().equals(expected)) {
 286:                 return true;
 287:             }
 288:         }
 289:         return false;
 290:     }
 291: 
 292:     private static int compareNumbers(String actual, String expected) {
 293:         if (actual == null) {
 294:             return Integer.MIN_VALUE;
 295:         }
 296:         try {
 297:             return Double.compare(Double.parseDouble(actual), Double.parseDouble(expected));
 298:         } catch (NumberFormatException error) {
 299:             return Integer.MIN_VALUE;
 300:         }
 301:     }
 302: 
 303:     private static void validateRuleIds(List<Rule> rules) {
 304:         Set<String> ids = new LinkedHashSet<>();
 305:         for (Rule rule : rules) {
 306:             if (!ids.add(rule.id)) {
 307:                 throw new IllegalArgumentException("duplicate rule id: " + rule.id);
 308:             }
 309:         }
 310:     }
 311: 
 312:     private static String requireToken(String value, String name) {
 313:         Objects.requireNonNull(value, name);
 314:         if (value.trim().isEmpty()) {
 315:             throw new IllegalArgumentException(name + " must not be empty");
 316:         }
 317:         return value;
 318:     }
 319: 
 320:     private static <T> List<T> immutableList(Collection<T> values) {
 321:         return Collections.unmodifiableList(
 322:                 new ArrayList<>(Objects.requireNonNull(values, "values")));
 323:     }
 324: 
 325:     private static <T> Set<T> immutableSet(Collection<T> values) {
 326:         return Collections.unmodifiableSet(
 327:                 new LinkedHashSet<>(Objects.requireNonNull(values, "values")));
 328:     }
 329: }
