  18: import java.util.ArrayDeque;
  19: import java.util.ArrayList;
  20: import java.util.Collections;
  21: import java.util.Comparator;
  22: import java.util.Deque;
  23: import java.util.LinkedHashMap;
  24: import java.util.List;
  25: import java.util.Map;
  26: import java.util.Objects;
  27: 
  28: /** Per-provider rolling health window and circuit breaker for authentication calls. */
  29: public final class ProviderHealthMonitor {
  30:     public enum CircuitState {
  31:         CLOSED,
  32:         OPEN,
  33:         HALF_OPEN
  34:     }
  35: 
  36:     public enum Outcome {
  37:         SUCCESS,
  38:         TIMEOUT,
  39:         AUTHENTICATION_REJECTED,
  40:         PROVIDER_ERROR,
  41:         NETWORK_ERROR,
  42:         CANCELLED
  43:     }
  44: 
  45:     public static final class Config {
  46:         public final int windowSize;
  47:         public final int minimumSamples;
  48:         public final double failureRateThreshold;
  49:         public final long latencyThresholdMillis;
  50:         public final long openDurationMillis;
  51:         public final int halfOpenSuccesses;
  52: 
  53:         public Config(
  54:                 int windowSize,
  55:                 int minimumSamples,
  56:                 double failureRateThreshold,
  57:                 long latencyThresholdMillis,
  58:                 long openDurationMillis,
  59:                 int halfOpenSuccesses) {
  60:             this.windowSize = windowSize;
  61:             this.minimumSamples = minimumSamples;
  62:             this.failureRateThreshold = failureRateThreshold;
  63:             this.latencyThresholdMillis = latencyThresholdMillis;
  64:             this.openDurationMillis = openDurationMillis;
  65:             this.halfOpenSuccesses = halfOpenSuccesses;
  66:             if (windowSize <= 0 || minimumSamples <= 0 || minimumSamples > windowSize) {
  67:                 throw new IllegalArgumentException("invalid sample window");
  68:             }
  69:             if (failureRateThreshold <= 0 || failureRateThreshold > 1) {
  70:                 throw new IllegalArgumentException("invalid failure threshold");
  71:             }
  72:             if (latencyThresholdMillis <= 0 || openDurationMillis <= 0) {
  73:                 throw new IllegalArgumentException("durations must be positive");
  74:             }
  75:             if (halfOpenSuccesses <= 0) {
  76:                 throw new IllegalArgumentException("half-open successes must be positive");
  77:             }
  78:         }
  79:     }
  80: 
  81:     public static final class Sample {
  82:         public final Outcome outcome;
  83:         public final long latencyMillis;
  84:         public final long timestamp;
  85: 
  86:         public Sample(Outcome outcome, long latencyMillis, long timestamp) {
  87:             this.outcome = Objects.requireNonNull(outcome, "outcome");
  88:             this.latencyMillis = latencyMillis;
  89:             this.timestamp = timestamp;
  90:             if (latencyMillis < 0 || timestamp < 0) {
  91:                 throw new IllegalArgumentException("sample values must not be negative");
  92:             }
  93:         }
  94: 
  95:         public boolean failed() {
  96:             return outcome == Outcome.TIMEOUT
  97:                     || outcome == Outcome.PROVIDER_ERROR
  98:                     || outcome == Outcome.NETWORK_ERROR;
  99:         }
 100:     }
 101: 
 102:     public static final class Health {
 103:         public final String providerId;
 104:         public final CircuitState state;
 105:         public final int samples;
 106:         public final int failures;
 107:         public final double failureRate;
 108:         public final long medianLatencyMillis;
 109:         public final long percentile95LatencyMillis;
 110:         public final long openUntil;
 111: 
 112:         Health(
 113:                 String providerId,
 114:                 CircuitState state,
 115:                 int samples,
 116:                 int failures,
 117:                 double failureRate,
 118:                 long medianLatencyMillis,
 119:                 long percentile95LatencyMillis,
 120:                 long openUntil) {
 121:             this.providerId = providerId;
 122:             this.state = state;
 123:             this.samples = samples;
 124:             this.failures = failures;
 125:             this.failureRate = failureRate;
 126:             this.medianLatencyMillis = medianLatencyMillis;
 127:             this.percentile95LatencyMillis = percentile95LatencyMillis;
 128:             this.openUntil = openUntil;
 129:         }
 130:     }
 131: 
 132:     private static final class ProviderState {
 133:         final String providerId;
 134:         final Deque<Sample> samples = new ArrayDeque<>();
 135:         CircuitState circuit = CircuitState.CLOSED;
 136:         long openUntil;
 137:         int halfOpenSuccesses;
 138:         boolean halfOpenProbeInFlight;
 139: 
 140:         ProviderState(String providerId) {
 141:             this.providerId = providerId;
 142:         }
 143:     }
 144: 
 145:     private final Config config;
 146:     private final Map<String, ProviderState> providers = new LinkedHashMap<>();
 147: 
 148:     public ProviderHealthMonitor(Config config) {
 149:         this.config = Objects.requireNonNull(config, "config");
 150:     }
 151: 
 152:     public synchronized boolean acquire(String providerId, long now) {
 153:         ProviderState state = state(providerId);
 154:         refreshCircuit(state, now);
 155:         if (state.circuit == CircuitState.OPEN) {
 156:             return false;
 157:         }
 158:         if (state.circuit == CircuitState.HALF_OPEN) {
 159:             if (state.halfOpenProbeInFlight) {
 160:                 return false;
 161:             }
 162:             state.halfOpenProbeInFlight = true;
 163:         }
 164:         return true;
 165:     }
 166: 
 167:     public synchronized void record(String providerId, Sample sample) {
 168:         ProviderState state = state(providerId);
 169:         state.samples.addLast(Objects.requireNonNull(sample, "sample"));
 170:         while (state.samples.size() > config.windowSize) {
 171:             state.samples.removeFirst();
 172:         }
 173:         if (state.circuit == CircuitState.HALF_OPEN) {
 174:             state.halfOpenProbeInFlight = false;
 175:             if (sample.failed()) {
 176:                 open(state, sample.timestamp);
 177:                 return;
 178:             }
 179:             state.halfOpenSuccesses++;
 180:             if (state.halfOpenSuccesses >= config.halfOpenSuccesses) {
 181:                 close(state);
 182:             }
 183:             return;
 184:         }
 185:         if (state.circuit == CircuitState.CLOSED && unhealthy(state)) {
 186:             open(state, sample.timestamp);
 187:         }
 188:     }
 189: 
 190:     public synchronized Health health(String providerId, long now) {
 191:         ProviderState state = state(providerId);
 192:         refreshCircuit(state, now);
 193:         List<Long> latencies = new ArrayList<>();
 194:         int failures = 0;
 195:         for (Sample sample : state.samples) {
 196:             latencies.add(sample.latencyMillis);
 197:             if (sample.failed()) {
 198:                 failures++;
 199:             }
 200:         }
 201:         Collections.sort(latencies);
 202:         double failureRate = state.samples.isEmpty()
 203:                 ? 0
 204:                 : failures / (double) state.samples.size();
 205:         return new Health(
 206:                 providerId,
 207:                 state.circuit,
 208:                 state.samples.size(),
 209:                 failures,
 210:                 failureRate,
 211:                 percentile(latencies, 0.50),
 212:                 percentile(latencies, 0.95),
 213:                 state.openUntil);
 214:     }
 215: 
 216:     public synchronized List<Health> snapshot(long now) {
 217:         List<Health> result = new ArrayList<>();
 218:         for (String providerId : providers.keySet()) {
 219:             result.add(health(providerId, now));
 220:         }
 221:         result.sort(Comparator.comparing(value -> value.providerId));
 222:         return Collections.unmodifiableList(result);
 223:     }
 224: 
 225:     public synchronized void reset(String providerId) {
 226:         ProviderState state = state(providerId);
 227:         state.samples.clear();
 228:         close(state);
 229:     }
 230: 
 231:     private ProviderState state(String providerId) {
 232:         String id = require(providerId, "providerId");
 233:         return providers.computeIfAbsent(id, ProviderState::new);
 234:     }
 235: 
 236:     private boolean unhealthy(ProviderState state) {
 237:         if (state.samples.size() < config.minimumSamples) {
 238:             return false;
 239:         }
 240:         int failures = 0;
 241:         List<Long> latencies = new ArrayList<>();
 242:         for (Sample sample : state.samples) {
 243:             if (sample.failed()) {
 244:                 failures++;
 245:             }
 246:             latencies.add(sample.latencyMillis);
 247:         }
 248:         Collections.sort(latencies);
 249:         double failureRate = failures / (double) state.samples.size();
 250:         return failureRate >= config.failureRateThreshold
 251:                 || percentile(latencies, 0.95) >= config.latencyThresholdMillis;
 252:     }
 253: 
 254:     private void refreshCircuit(ProviderState state, long now) {
 255:         if (state.circuit == CircuitState.OPEN && state.openUntil <= now) {
 256:             state.circuit = CircuitState.HALF_OPEN;
 257:             state.halfOpenProbeInFlight = false;
 258:             state.halfOpenSuccesses = 0;
 259:         }
 260:     }
 261: 
 262:     private void open(ProviderState state, long now) {
 263:         state.circuit = CircuitState.OPEN;
 264:         state.openUntil = now + config.openDurationMillis;
 265:         state.halfOpenProbeInFlight = false;
 266:         state.halfOpenSuccesses = 0;
 267:     }
 268: 
 269:     private static void close(ProviderState state) {
 270:         state.circuit = CircuitState.CLOSED;
 271:         state.openUntil = 0;
 272:         state.halfOpenProbeInFlight = false;
 273:         state.halfOpenSuccesses = 0;
 274:     }
 275: 
 276:     private static long percentile(List<Long> ordered, double percentile) {
 277:         if (ordered.isEmpty()) {
 278:             return 0;
 279:         }
 280:         int index = (int) Math.ceil(percentile * ordered.size()) - 1;
 281:         return ordered.get(Math.max(0, Math.min(index, ordered.size() - 1)));
 282:     }
 283: 
 284:     private static String require(String value, String name) {
 285:         Objects.requireNonNull(value, name);
 286:         if (value.trim().isEmpty()) {
 287:             throw new IllegalArgumentException(name + " must not be empty");
 288:         }
 289:         return value;
 290:     }
 291: }
