  16: package com.cockpitbench.foundation.core;
  17: 
  18: import java.util.ArrayList;
  19: import java.util.Collection;
  20: import java.util.Collections;
  21: import java.util.Comparator;
  22: import java.util.LinkedHashMap;
  23: import java.util.LinkedHashSet;
  24: import java.util.List;
  25: import java.util.Map;
  26: import java.util.Objects;
  27: import java.util.Set;
  28: 
  29: /** Field-level account reconciliation with explicit conflicts and deterministic ordering. */
  30: public final class RecordReconciler {
  31:     public enum Authority {
  32:         LOCAL,
  33:         PROVIDER,
  34:         FLEET,
  35:         OWNER
  36:     }
  37: 
  38:     public enum Strategy {
  39:         NEWEST,
  40:         AUTHORITY,
  41:         LOCAL_ONLY,
  42:         REMOTE_ONLY,
  43:         MANUAL
  44:     }
  45: 
  46:     public static final class Value {
  47:         public final String content;
  48:         public final long changedAt;
  49:         public final Authority authority;
  50:         public final boolean tombstone;
  51: 
  52:         public Value(String content, long changedAt, Authority authority, boolean tombstone) {
  53:             this.content = content == null ? "" : content;
  54:             this.changedAt = changedAt;
  55:             this.authority = Objects.requireNonNull(authority, "authority");
  56:             this.tombstone = tombstone;
  57:             if (changedAt < 0) {
  58:                 throw new IllegalArgumentException("changedAt must not be negative");
  59:             }
  60:         }
  61: 
  62:         public boolean semanticallyEquals(Value other) {
  63:             return other != null
  64:                     && content.equals(other.content)
  65:                     && tombstone == other.tombstone;
  66:         }
  67:     }
  68: 
  69:     public static final class Record {
  70:         public final String accountId;
  71:         public final long revision;
  72:         public final Map<String, Value> fields;
  73: 
  74:         public Record(String accountId, long revision, Map<String, Value> fields) {
  75:             this.accountId = require(accountId, "accountId");
  76:             this.revision = revision;
  77:             this.fields = Collections.unmodifiableMap(
  78:                     new LinkedHashMap<>(Objects.requireNonNull(fields, "fields")));
  79:             if (revision < 0) {
  80:                 throw new IllegalArgumentException("revision must not be negative");
  81:             }
  82:             for (String field : this.fields.keySet()) {
  83:                 require(field, "field");
  84:             }
  85:         }
  86:     }
  87: 
  88:     public static final class FieldPolicy {
  89:         public final String field;
  90:         public final Strategy strategy;
  91:         public final List<Authority> authorityOrder;
  92:         public final boolean deletionWins;
  93: 
  94:         public FieldPolicy(
  95:                 String field,
  96:                 Strategy strategy,
  97:                 Collection<Authority> authorityOrder,
  98:                 boolean deletionWins) {
  99:             this.field = require(field, "field");
 100:             this.strategy = Objects.requireNonNull(strategy, "strategy");
 101:             this.authorityOrder = Collections.unmodifiableList(
 102:                     new ArrayList<>(Objects.requireNonNull(authorityOrder, "authorityOrder")));
 103:             this.deletionWins = deletionWins;
 104:             if (strategy == Strategy.AUTHORITY && this.authorityOrder.isEmpty()) {
 105:                 throw new IllegalArgumentException("authority strategy needs an order");
 106:             }
 107:         }
 108:     }
 109: 
 110:     public static final class Conflict {
 111:         public final String field;
 112:         public final Value base;
 113:         public final Value local;
 114:         public final Value remote;
 115:         public final String reason;
 116: 
 117:         Conflict(String field, Value base, Value local, Value remote, String reason) {
 118:             this.field = field;
 119:             this.base = base;
 120:             this.local = local;
 121:             this.remote = remote;
 122:             this.reason = reason;
 123:         }
 124:     }
 125: 
 126:     public static final class Change {
 127:         public final String field;
 128:         public final Value before;
 129:         public final Value after;
 130:         public final String source;
 131: 
 132:         Change(String field, Value before, Value after, String source) {
 133:             this.field = field;
 134:             this.before = before;
 135:             this.after = after;
 136:             this.source = source;
 137:         }
 138:     }
 139: 
 140:     public static final class Result {
 141:         public final Record merged;
 142:         public final List<Conflict> conflicts;
 143:         public final List<Change> changes;
 144: 
 145:         Result(Record merged, List<Conflict> conflicts, List<Change> changes) {
 146:             this.merged = merged;
 147:             this.conflicts = Collections.unmodifiableList(new ArrayList<>(conflicts));
 148:             this.changes = Collections.unmodifiableList(new ArrayList<>(changes));
 149:         }
 150: 
 151:         public boolean requiresUserResolution() {
 152:             return !conflicts.isEmpty();
 153:         }
 154:     }
 155: 
 156:     private final Map<String, FieldPolicy> policies;
 157: 
 158:     public RecordReconciler(Collection<FieldPolicy> policies) {
 159:         Map<String, FieldPolicy> indexed = new LinkedHashMap<>();
 160:         for (FieldPolicy policy : Objects.requireNonNull(policies, "policies")) {
 161:             if (indexed.put(policy.field, policy) != null) {
 162:                 throw new IllegalArgumentException("duplicate field policy: " + policy.field);
 163:             }
 164:         }
 165:         this.policies = Collections.unmodifiableMap(indexed);
 166:     }
 167: 
 168:     public Result reconcile(Record base, Record local, Record remote) {
 169:         validateIdentity(base, local, remote);
 170:         Set<String> fieldNames = new LinkedHashSet<>();
 171:         fieldNames.addAll(base.fields.keySet());
 172:         fieldNames.addAll(local.fields.keySet());
 173:         fieldNames.addAll(remote.fields.keySet());
 174:         List<String> ordered = new ArrayList<>(fieldNames);
 175:         ordered.sort(Comparator.naturalOrder());
 176: 
 177:         Map<String, Value> merged = new LinkedHashMap<>();
 178:         List<Conflict> conflicts = new ArrayList<>();
 179:         List<Change> changes = new ArrayList<>();
 180:         for (String field : ordered) {
 181:             Value baseValue = base.fields.get(field);
 182:             Value localValue = local.fields.get(field);
 183:             Value remoteValue = remote.fields.get(field);
 184:             FieldPolicy policy = policies.getOrDefault(
 185:                     field,
 186:                     new FieldPolicy(field, Strategy.MANUAL, Collections.emptyList(), false));
 187:             Selection selection = select(policy, baseValue, localValue, remoteValue);
 188:             if (selection.conflictReason != null) {
 189:                 conflicts.add(new Conflict(
 190:                         field,
 191:                         baseValue,
 192:                         localValue,
 193:                         remoteValue,
 194:                         selection.conflictReason));
 195:             }
 196:             if (selection.value != null && !selection.value.tombstone) {
 197:                 merged.put(field, selection.value);
 198:             }
 199:             if (!sameValue(baseValue, selection.value)) {
 200:                 changes.add(new Change(field, baseValue, selection.value, selection.source));
 201:             }
 202:         }
 203:         long revision = Math.max(local.revision, remote.revision) + 1;
 204:         return new Result(
 205:                 new Record(base.accountId, revision, merged),
 206:                 conflicts,
 207:                 changes);
 208:     }
 209: 
 210:     private Selection select(
 211:             FieldPolicy policy,
 212:             Value base,
 213:             Value local,
 214:             Value remote) {
 215:         boolean localChanged = !sameValue(base, local);
 216:         boolean remoteChanged = !sameValue(base, remote);
 217:         if (!localChanged && !remoteChanged) {
 218:             return new Selection(base, "base", null);
 219:         }
 220:         if (localChanged && !remoteChanged) {
 221:             return new Selection(local, "local", null);
 222:         }
 223:         if (!localChanged) {
 224:             return new Selection(remote, "remote", null);
 225:         }
 226:         if (sameValue(local, remote)) {
 227:             return new Selection(local, "both", null);
 228:         }
 229:         if (policy.deletionWins && isDeletion(local, remote)) {
 230:             Value deletion = local != null && local.tombstone ? local : remote;
 231:             return new Selection(deletion, "deletion", null);
 232:         }
 233:         switch (policy.strategy) {
 234:             case LOCAL_ONLY:
 235:                 return new Selection(local, "local-policy", null);
 236:             case REMOTE_ONLY:
 237:                 return new Selection(remote, "remote-policy", null);
 238:             case NEWEST:
 239:                 return newest(local, remote);
 240:             case AUTHORITY:
 241:                 return authoritative(policy, local, remote);
 242:             case MANUAL:
 243:             default:
 244:                 Value provisional = newest(local, remote).value;
 245:                 return new Selection(provisional, "provisional", "concurrent edits require review");
 246:         }
 247:     }
 248: 
 249:     private static Selection newest(Value local, Value remote) {
 250:         if (local == null) {
 251:             return new Selection(remote, "remote-newest", null);
 252:         }
 253:         if (remote == null) {
 254:             return new Selection(local, "local-newest", null);
 255:         }
 256:         if (local.changedAt == remote.changedAt) {
 257:             return new Selection(
 258:                     local,
 259:                     "local-tie-break",
 260:                     "equal timestamps with different values");
 261:         }
 262:         return local.changedAt > remote.changedAt
 263:                 ? new Selection(local, "local-newest", null)
 264:                 : new Selection(remote, "remote-newest", null);
 265:     }
 266: 
 267:     private static Selection authoritative(FieldPolicy policy, Value local, Value remote) {
 268:         if (local == null) {
 269:             return new Selection(remote, "remote-authority", null);
 270:         }
 271:         if (remote == null) {
 272:             return new Selection(local, "local-authority", null);
 273:         }
 274:         int localRank = rank(policy.authorityOrder, local.authority);
 275:         int remoteRank = rank(policy.authorityOrder, remote.authority);
 276:         if (localRank == remoteRank) {
 277:             Selection newest = newest(local, remote);
 278:             return new Selection(newest.value, newest.source, "equal authority produced conflict");
 279:         }
 280:         return localRank < remoteRank
 281:                 ? new Selection(local, "local-authority", null)
 282:                 : new Selection(remote, "remote-authority", null);
 283:     }
 284: 
 285:     private static int rank(List<Authority> order, Authority authority) {
 286:         int index = order.indexOf(authority);
 287:         return index < 0 ? Integer.MAX_VALUE : index;
 288:     }
 289: 
 290:     private static boolean isDeletion(Value first, Value second) {
 291:         return first != null && first.tombstone || second != null && second.tombstone;
 292:     }
 293: 
 294:     private static boolean sameValue(Value first, Value second) {
 295:         if (first == null) {
 296:             return second == null;
 297:         }
 298:         return first.semanticallyEquals(second);
 299:     }
 300: 
 301:     private static void validateIdentity(Record base, Record local, Record remote) {
 302:         Objects.requireNonNull(base, "base");
 303:         Objects.requireNonNull(local, "local");
 304:         Objects.requireNonNull(remote, "remote");
 305:         if (!base.accountId.equals(local.accountId) || !base.accountId.equals(remote.accountId)) {
 306:             throw new IllegalArgumentException("cannot reconcile different accounts");
 307:         }
 308:         if (local.revision < base.revision || remote.revision < base.revision) {
 309:             throw new IllegalArgumentException("branch revision precedes base");
 310:         }
 311:     }
 312: 
 313:     private static String require(String value, String name) {
 314:         Objects.requireNonNull(value, name);
 315:         if (value.trim().isEmpty()) {
 316:             throw new IllegalArgumentException(name + " must not be empty");
 317:         }
 318:         return value;
 319:     }
 320: 
 321:     private static final class Selection {
 322:         final Value value;
 323:         final String source;
 324:         final String conflictReason;
 325: 
 326:         Selection(Value value, String source, String conflictReason) {
 327:             this.value = value;
 328:             this.source = source;
 329:             this.conflictReason = conflictReason;
 330:         }
 331:     }
 332: }
