  29: /** Resolves inherited cockpit roles with deny precedence and zone constraints. */
  30: public final class RoleAuthorizationGraph {
  31:     public enum Effect {
  32:         ALLOW,
  33:         DENY
  34:     }
  35: 
  36:     public static final class Permission {
  37:         public final String operation;
  38:         public final Effect effect;
  39:         public final Set<String> zones;
  40:         public final boolean recentAuthenticationRequired;
  41: 
  42:         public Permission(
  43:                 String operation,
  44:                 Effect effect,
  45:                 Collection<String> zones,
  46:                 boolean recentAuthenticationRequired) {
  47:             this.operation = require(operation, "operation");
  48:             this.effect = Objects.requireNonNull(effect, "effect");
