 124:     public static final class Decision {
 125:         public final boolean allowed;
 126:         public final boolean reauthenticationRequired;
 127:         public final String reason;
 128:         public final List<String> effectiveRoles;
 129:         public final List<Trace> trace;
 130: 
 131:         Decision(
 132:                 boolean allowed,
 133:                 boolean reauthenticationRequired,
 134:                 String reason,
 135:                 List<String> effectiveRoles,
 136:                 List<Trace> trace) {
 137:             this.allowed = allowed;
 138:             this.reauthenticationRequired = reauthenticationRequired;
 139:             this.reason = reason;
 140:             this.effectiveRoles = Collections.unmodifiableList(
 141:                     new ArrayList<>(effectiveRoles));
 142:             this.trace = Collections.unmodifiableList(new ArrayList<>(trace));
 143:         }
