 148:     public RoleAuthorizationGraph(Collection<Role> roles) {
 149:         Map<String, Role> indexed = new LinkedHashMap<>();
 150:         for (Role role : Objects.requireNonNull(roles, "roles")) {
 151:             if (indexed.put(role.id, role) != null) {
 152:                 throw new IllegalArgumentException("duplicate role: " + role.id);
 153:             }
 154:         }
 155:         validateParents(indexed);
 156:         validateAcyclic(indexed);
 157:         this.roles = Collections.unmodifiableMap(indexed);
 158:     }
 159: 
 160:     public Decision authorize(
 161:             Collection<Assignment> assignments,
 162:             String operation,
 163:             String zone,
 164:             boolean recentlyAuthenticated,
 165:             long now) {
 166:         String requestedOperation = require(operation, "operation");
 167:         String requestedZone = require(zone, "zone");
 168:         Set<String> active = new LinkedHashSet<>();
 169:         for (Assignment assignment : Objects.requireNonNull(assignments, "assignments")) {
 170:             Role role = roles.get(assignment.roleId);
 171:             if (role == null || !role.assignable) {
 172:                 continue;
 173:             }
 174:             if (assignment.validFrom <= now && assignment.validUntil > now
 175:                     && zoneMatches(assignment.zone, requestedZone)) {
 176:                 collectRole(assignment.roleId, active);
 177:             }
 178:         }
 179:         List<String> orderedRoles = new ArrayList<>(active);
 180:         Collections.sort(orderedRoles);
 181:         List<Trace> trace = new ArrayList<>();
 182:         boolean allowed = false;
 183:         boolean reauthenticationRequired = false;
 184:         for (String roleId : orderedRoles) {
 185:             Role role = roles.get(roleId);
 186:             for (Permission permission : role.permissions) {
 187:                 if (!permission.operation.equals(requestedOperation)
 188:                         && !permission.operation.equals("*")) {
 189:                     continue;
 190:                 }
 191:                 boolean zoneMatched = permission.zones.contains("all")
 192:                         || permission.zones.contains(requestedZone);
 193:                 boolean authenticationSatisfied = !permission.recentAuthenticationRequired
 194:                         || recentlyAuthenticated;
 195:                 trace.add(new Trace(
 196:                         roleId,
 197:                         permission.operation,
 198:                         permission.effect,
 199:                         zoneMatched,
 200:                         authenticationSatisfied));
 201:                 if (!zoneMatched) {
 202:                     continue;
 203:                 }
 204:                 if (permission.effect == Effect.DENY) {
 205:                     return new Decision(
 206:                             false,
 207:                             false,
 208:                             "explicit deny from " + roleId,
 209:                             orderedRoles,
 210:                             trace);
 211:                 }
 212:                 if (!authenticationSatisfied) {
 213:                     reauthenticationRequired = true;
 214:                     continue;
 215:                 }
 216:                 allowed = true;
 217:             }
 218:         }
 219:         if (allowed) {
 220:             return new Decision(true, false, "allowed by effective role", orderedRoles, trace);
 221:         }
 222:         if (reauthenticationRequired) {
 223:             return new Decision(
 224:                     false,
 225:                     true,
 226:                     "recent authentication required",
 227:                     orderedRoles,
 228:                     trace);
 229:         }
 230:         return new Decision(false, false, "no matching grant", orderedRoles, trace);
 231:     }
