 184:             this.id = require(id, "id");
 185:             this.definition = Objects.requireNonNull(definition, "definition");
 186:             this.context = new Context(input);
 187:             for (String stepId : definition.order) {
 188:                 states.put(stepId, StepStatus.PENDING);
 189:             }
