 224:     public Execution start(
 225:             String executionId,
 226:             Definition definition,
 227:             Map<String, String> input) {
 228:         Execution execution = new Execution(executionId, definition, input);
 229:         runReadySteps(execution);
 230:         return execution;
 231:     }
 232: 
 233:     public void resume(Execution execution, String stepId, Map<String, String> values) {
 234:         Objects.requireNonNull(execution, "execution");
 235:         synchronized (execution) {
 236:             if (execution.status != Status.WAITING || !execution.waitingStep.equals(stepId)) {
 237:                 throw new IllegalStateException("execution is not waiting for " + stepId);
 238:             }
 239:             for (Map.Entry<String, String> value : values.entrySet()) {
 240:                 execution.context.put(value.getKey(), value.getValue());
 241:             }
 242:             execution.states.put(stepId, StepStatus.SUCCEEDED);
 243:             execution.completed.push(stepId);
 244:             execution.waitingStep = "";
 245:             execution.status = Status.RUNNING;
 246:             notifyObservers(execution.id, stepId, StepStatus.SUCCEEDED);
 247:         }
 248:         runReadySteps(execution);
 249:     }
 250: 
 251:     public void cancel(Execution execution) {
 252:         Objects.requireNonNull(execution, "execution");
 253:         synchronized (execution) {
 254:             if (EnumSetTerminal.contains(execution.status)) {
 255:                 return;
 256:             }
 257:             compensate(execution);
 258:             execution.status = Status.CANCELLED;
 259:             execution.waitingStep = "";
 260:         }
 261:     }
 262: 
 263:     private void runReadySteps(Execution execution) {
 264:         synchronized (execution) {
 265:             if (EnumSetTerminal.contains(execution.status)) {
 266:                 return;
 267:             }
 268:             execution.status = Status.RUNNING;
 269:             boolean progressed;
 270:             do {
 271:                 progressed = false;
 272:                 for (String stepId : execution.definition.order) {
 273:                     if (execution.states.get(stepId) != StepStatus.PENDING) {
 274:                         continue;
 275:                     }
 276:                     Step step = execution.definition.steps.get(stepId);
 277:                     if (!dependenciesSucceeded(step, execution.states)) {
 278:                         continue;
 279:                     }
 280:                     progressed = true;
 281:                     if (!executeStep(execution, step)) {
 282:                         return;
 283:                     }
 284:                 }
 285:             } while (progressed);
 286:             if (allSucceeded(execution.states)) {
 287:                 execution.status = Status.COMPLETED;
 288:                 return;
 289:             }
 290:             if (execution.status == Status.RUNNING) {
 291:                 execution.status = Status.FAILED;
 292:                 execution.errorCode = "WORKFLOW_STALLED";
 293:                 compensate(execution);
 294:             }
 295:         }
 296:     }
 297: 
 298:     private boolean executeStep(Execution execution, Step step) {
 299:         execution.states.put(step.id, StepStatus.RUNNING);
 300:         notifyObservers(execution.id, step.id, StepStatus.RUNNING);
 301:         long started = clock.now();
 302:         try {
 303:             ActionResult result = step.action.execute(execution.context);
 304:             if (clock.now() - started > step.timeoutMillis) {
 305:                 fail(execution, step, "STEP_TIMEOUT");
 306:                 return false;
 307:             }
 308:             for (Map.Entry<String, String> output : result.outputs.entrySet()) {
 309:                 execution.context.put(output.getKey(), output.getValue());
 310:             }
 311:             if (result.waiting) {
 312:                 execution.status = Status.WAITING;
 313:                 execution.waitingStep = step.id;
 314:                 execution.errorCode = result.code;
 315:                 return false;
 316:             }
 317:             if (!result.success) {
 318:                 fail(execution, step, result.code);
 319:                 return false;
 320:             }
 321:             execution.states.put(step.id, StepStatus.SUCCEEDED);
 322:             execution.completed.push(step.id);
 323:             notifyObservers(execution.id, step.id, StepStatus.SUCCEEDED);
 324:             return true;
 325:         } catch (Exception error) {
 326:             fail(execution, step, error.getClass().getSimpleName());
 327:             return false;
 328:         }
 329:     }
 330: 
 331:     private void fail(Execution execution, Step step, String code) {
 332:         execution.states.put(step.id, StepStatus.FAILED);
 333:         execution.status = Status.FAILED;
 334:         execution.errorCode = code;
 335:         notifyObservers(execution.id, step.id, StepStatus.FAILED);
 336:         compensate(execution);
 337:     }
 338: 
 339:     private void compensate(Execution execution) {
 340:         while (!execution.completed.isEmpty()) {
 341:             String stepId = execution.completed.pop();
 342:             Step step = execution.definition.steps.get(stepId);
 343:             if (!step.compensatable) {
 344:                 continue;
 345:             }
 346:             try {
 347:                 step.action.compensate(execution.context);
 348:             } catch (Exception ignored) {
 349:                 execution.errorCode = execution.errorCode + ":COMPENSATION_FAILED:" + stepId;
 350:             }
 351:         }
 352:     }
 353: 
 354:     private synchronized void notifyObservers(
 355:             String executionId,
 356:             String stepId,
 357:             StepStatus status) {
 358:         for (Observer observer : new ArrayList<>(observers)) {
 359:             observer.onTransition(executionId, stepId, status);
 360:         }
 361:     }
 362: 
 363:     private static boolean dependenciesSucceeded(
 364:             Step step,
 365:             Map<String, StepStatus> states) {
 366:         for (String dependency : step.dependencies) {
 367:             if (states.get(dependency) != StepStatus.SUCCEEDED) {
 368:                 return false;
 369:             }
 370:         }
 371:         return true;
 372:     }
 373: 
 374:     private static boolean allSucceeded(Map<String, StepStatus> states) {
 375:         for (StepStatus state : states.values()) {
 376:             if (state != StepStatus.SUCCEEDED && state != StepStatus.SKIPPED) {
 377:                 return false;
 378:             }
 379:         }
 380:         return true;
 381:     }
 382: 
 383:     private static void validateDependencies(Map<String, Step> steps) {
 384:         for (Step step : steps.values()) {
 385:             if (step.dependencies.contains(step.id)) {
 386:                 throw new IllegalArgumentException("step depends on itself: " + step.id);
 387:             }
 388:             for (String dependency : step.dependencies) {
 389:                 if (!steps.containsKey(dependency)) {
 390:                     throw new IllegalArgumentException(
 391:                             "unknown dependency " + dependency + " for " + step.id);
 392:                 }
 393:             }
 394:         }
 395:     }
 396: 
 397:     private static List<String> topologicalOrder(Map<String, Step> steps) {
 398:         List<String> result = new ArrayList<>();
 399:         Set<String> visiting = new LinkedHashSet<>();
 400:         Set<String> visited = new LinkedHashSet<>();
 401:         for (String stepId : steps.keySet()) {
 402:             visit(stepId, steps, visiting, visited, result);
 403:         }
 404:         return result;
 405:     }
 406: 
 407:     private static void visit(
 408:             String stepId,
 409:             Map<String, Step> steps,
 410:             Set<String> visiting,
 411:             Set<String> visited,
 412:             List<String> result) {
 413:         if (visited.contains(stepId)) {
 414:             return;
 415:         }
 416:         if (!visiting.add(stepId)) {
 417:             throw new IllegalArgumentException("workflow dependency cycle at " + stepId);
 418:         }
 419:         for (String dependency : steps.get(stepId).dependencies) {
 420:             visit(dependency, steps, visiting, visited, result);
 421:         }
 422:         visiting.remove(stepId);
 423:         visited.add(stepId);
 424:         result.add(stepId);
 425:     }
 426: 
 427:     private static String require(String value, String name) {
 428:         Objects.requireNonNull(value, name);
 429:         if (value.trim().isEmpty()) {
 430:             throw new IllegalArgumentException(name + " must not be empty");
 431:         }
 432:         return value;
 433:     }
 434: 
 435:     private static final Set<Status> EnumSetTerminal =
 436:             Collections.unmodifiableSet(new LinkedHashSet<>(java.util.Arrays.asList(
 437:                     Status.COMPLETED,
 438:                     Status.FAILED,
 439:                     Status.CANCELLED)));
 440: }

