  31: public final class WorkflowEngineTest {
  32:     @Test
  33:     public void dependencyOrderAndOutputsAreDeterministic() {
  34:         MutableClock clock = new MutableClock(100);
  35:         WorkflowEngine engine = new WorkflowEngine(clock);
  36:         List<String> observed = new ArrayList<>();
  37:         engine.addObserver((execution, step, state) -> observed.add(step + ":" + state));
  38:         WorkflowEngine.Step lookup = step(
  39:                 "lookup",
  40:                 Collections.emptyList(),
  41:                 context -> WorkflowEngine.ActionResult.success(
  42:                         singleton("account", "driver-1")));
  43:         WorkflowEngine.Step verify = step(
  44:                 "verify",
  45:                 Collections.singletonList("lookup"),
  46:                 context -> {
  47:                     assertEquals("driver-1", context.require("account"));
  48:                     return WorkflowEngine.ActionResult.success(
  49:                             singleton("verified", "true"));
  50:                 });
  51:         WorkflowEngine.Step audit = step(
  52:                 "audit",
  53:                 Collections.singletonList("verify"),
  54:                 context -> WorkflowEngine.ActionResult.success(
  55:                         singleton("audit", context.require("verified"))));
  56:         WorkflowEngine.Definition definition = new WorkflowEngine.Definition(
  57:                 "sign-in",
  58:                 4,
  59:                 Arrays.asList(audit, verify, lookup));
  60: 
  61:         WorkflowEngine.Execution execution = engine.start(
  62:                 "run-1",
  63:                 definition,
  64:                 Collections.emptyMap());
  65: 
  66:         assertEquals(WorkflowEngine.Status.COMPLETED, execution.status());
  67:         assertEquals("true", execution.context.get("audit"));
  68:         assertEquals("lookup:RUNNING", observed.get(0));
  69:         assertEquals("audit:SUCCEEDED", observed.get(observed.size() - 1));
  70:     }
