  72:     @Test
  73:     public void waitingStepCanBeResumedWithUserInput() {
  74:         MutableClock clock = new MutableClock(10);
  75:         WorkflowEngine engine = new WorkflowEngine(clock);
  76:         WorkflowEngine.Step consent = step(
  77:                 "consent",
  78:                 Collections.emptyList(),
  79:                 context -> WorkflowEngine.ActionResult.waiting(
  80:                         "USER_CONSENT",
