   1: package com.cockpitbench.foundation.core;
   2: import java.util.*;
   3: public final class InMemoryRepository<T> implements Repository<T> {
   4:  private final Map<String,T> values=new LinkedHashMap<>();
   5:  @Override public synchronized T find(String id){return values.get(id);}
   6:  @Override public synchronized List<T> snapshot(){return Collections.unmodifiableList(new ArrayList<>(values.values()));}
   7:  @Override public synchronized void save(String id,T value){values.put(Objects.requireNonNull(id),Objects.requireNonNull(value));}
   8:  @Override public synchronized void remove(String id){values.remove(id);}
   9: }
