   3: public final class OperationScheduler implements AutoCloseable { private final ScheduledExecutorService executor;private final Map<String,ScheduledFuture<?>> tasks=new HashMap<>();
   4:  public OperationScheduler(ScheduledExecutorService value){executor=Objects.requireNonNull(value);}public synchronized void schedule(String key,Runnable task,long delay){cancel(key);tasks.put(key,executor.schedule(()->{try{task.run();}finally{completed(key);}},delay,TimeUnit.MILLISECONDS));}
